import{RECITERS}from './quran-reciters.js';
export const RECOGNITION_CACHE='salah-quran-recognition-v2';
export function validRecognitionCatalog(value,index){
 if(value?.schema!==1||value.algorithm!=='salah-landmarks-v1'||value.rate!==8000||value.hop!==256||!['fingerprints-v1.bin.gz','fingerprints-v2.bin.gz'].includes(value.fingerprints)||!Number.isInteger(value.packedBytes)||value.packedBytes<8||value.packedBytes>12*1024*1024||!(/^[a-f0-9]{64}$/).test(value.packedSha256)||!Number.isInteger(value.bytes)||value.bytes<8||value.bytes>24*1024*1024||value.bytes%8||!(/^[a-f0-9]{64}$/).test(value.sha256)||!Array.isArray(value.tracks)||!value.tracks.length||value.tracks.length>255)return false;
 return value.tracks.every(track=>RECITERS.some(r=>r.id===track.reciter)&&Number.isInteger(track.surah)&&index.surahs[track.surah-1]&&Number.isFinite(track.duration)&&track.duration>0&&track.duration<2400&&Array.isArray(track.timings)&&(track.ayahTiming===false?track.timings.length===0:track.timings.filter(r=>r.ayah>0).length===index.surahs[track.surah-1].ayahs&&track.timings.every((row,i,all)=>Number.isInteger(row.ayah)&&row.ayah>=0&&row.ayah<=index.surahs[track.surah-1].ayahs&&row.ayah===i+(all[0].ayah===0?0:1)&&Number.isFinite(row.start)&&Number.isFinite(row.end)&&row.start>=0&&row.end>row.start&&row.end<=track.duration+1.5&&(!i||row.start>=all[i-1].end))));
}
export async function loadRecognitionData(index,{signal,onCatalog=()=>{},fetcher=fetch,cacheStorage=globalThis.caches}={}){
 const base=new URL('../data/recognition/',import.meta.url),metaUrl=new URL('catalog-v2.json',base).href,controller=new AbortController(),abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();const timer=setTimeout(abort,90000);let cache;
 async function response(url){try{cache??=await cacheStorage?.open(RECOGNITION_CACHE);const saved=await cache?.match(url);if(saved)return saved;}catch{}const value=await fetcher(url,{signal:controller.signal,credentials:'omit'});if(!value.ok)throw Error('База пока недоступна');return value;}
 try{
 const meta=await response(metaUrl),text=await meta.text();if(text.length>500000)throw Error('Некорректная база');const catalog=JSON.parse(text);if(!validRecognitionCatalog(catalog,index)){try{await cache?.delete(metaUrl);}catch{}throw Error('Некорректная база');}onCatalog(catalog);
 const binaryUrl=new URL(catalog.fingerprints,base).href,binary=await response(binaryUrl),packed=await binary.arrayBuffer();if(packed.byteLength!==catalog.packedBytes||[...new Uint8Array(await crypto.subtle.digest('SHA-256',packed))].map(n=>n.toString(16).padStart(2,'0')).join('')!==catalog.packedSha256){try{await cache?.delete(binaryUrl);}catch{}throw Error('База повреждена. Повторите загрузку.');}if(typeof DecompressionStream!=='function')throw Error('Для распознавания обновите браузер или Android System WebView.');const bytes=await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(controller.signal.aborted)throw Error('Отменено');
 const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');if(bytes.byteLength!==catalog.bytes||digest!==catalog.sha256){try{await cache?.delete(binaryUrl);}catch{}throw Error('Базу не удалось проверить. Повторите загрузку.');}
 const pairs=new DataView(bytes);let previous=0;for(let i=0;i<bytes.byteLength;i+=8){const hash=pairs.getUint32(i,true),code=pairs.getUint32(i+4,true),track=catalog.tracks[code>>>24];if(hash<previous||!track||(code&0xffffff)*.032>track.duration)throw Error('Повреждена база распознавания');previous=hash;}
 if(controller.signal.aborted)throw Error('Отменено');try{await cache?.put(metaUrl,new Response(text,{headers:{'Content-Type':'application/json'}}));await cache?.put(binaryUrl,new Response(packed));}catch{}
 return{catalog,bytes};
 }finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
}
